var n=`0320-soupe-a-loignon`;var i=`world-0320`;var o=`FR`;var a=`western-europe`;var r=4;var s=70;var u={en:`Soupe à l'Oignon`,ua:`Французький цибулевий суп`};var l={en:`A traditional France dish made with yellow onion, thyme, bay leaf, baguette. This home-style preparation follows its characteristic cooking method and uses measured ingredients.`,ua:`Традиційна страва кухні країни Франція. Основні інгредієнти: жовта цибуля, чебрець, лавровий лист, багет. Домашній варіант із характерною технологією та поетапно розподіленими продуктами.`};var m=[{en:`Slice the onions thinly and caramelize them slowly in butter and oil, stirring frequently, until deep amber, about 35–40 minutes.`,ua:`Тонко наріжте цибулю й повільно карамелізуйте на суміші масла й олії, часто помішуючи, до насичено-бурштинового кольору близько 35–40 хвилин.`,t:[`chopping`,`sauteing`],m:38,i:[[`yellow-onion`,850,`g`],[`unsalted-butter`,75,`g`],[`extra-virgin-olive-oil`,35,`ml`],[`white-granulated-sugar`,12,`g`]]},{en:`Combine these ingredients in a pot, bring just to a boil and skim any foam. Simmer gently for about 20 minutes to make a flavorful base.`,ua:`З’єднайте складники в каструлі, доведіть майже до кипіння та зніміть піну. Варіть на малому вогні приблизно 20 хвилин для насиченої основи.`,t:[`simmering`,`skimming-foam`],m:20,i:[[`beef-stock`,1300,`ml`],[`dry-white-wine`,140,`ml`],[`thyme`,2,`sprig`],[`bay-leaf`,2,`leaf`]]},{en:`Toast these ingredients over medium heat for about 5 minutes, turning frequently to prevent scorching.`,ua:`Підсмажуйте зазначені складники на середньому вогні приблизно 5 хвилин, часто перевертаючи, щоб не підгоріли.`,t:[`dry-toasting`],m:5,i:[[`baguette`,200,`g`]]},{en:`Roast in a preheated 190°C oven for about 7 minutes until nicely browned and fully cooked; turn once if needed.`,ua:`Запікайте в розігрітій до 190°C духовці приблизно 7 хвилин до рум’яності й готовності; за потреби переверніть.`,t:[`roasting`],m:7,i:[[`gruyere`,200,`g`]]}];var g={slug:n,id:i,country:`FR`,region:a,servings:4,minutes:70,title:u,text:l,steps:m};export{o as country,g as default,i as id,s as minutes,a as region,r as servings,n as slug,m as steps,l as text,u as title};